arduino.setup:
Serial.begin(9600);
pinMode(${IN}, OUTPUT);
pinMode(${OUT}, INPUT);
Serial.println("NOT Gate ready");

arduino.loop:
digitalWrite(${IN}, LOW);
delay(10);
Serial.print("NOT | 0 -> ");
Serial.println(digitalRead(${OUT})?"HIGH":"LOW");
delay(1000);
digitalWrite(${IN}, HIGH);
delay(10);
Serial.print("NOT | 1 -> ");
Serial.println(digitalRead(${OUT})?"HIGH":"LOW");
delay(1000);
